UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Budd-Chiari Syndrome","body":"**Triad:** abdominal pain + ascites + hepatomegaly + jaundice in a patient with hypercoagulable risk factors (myeloproliferative neoplasm, OCP, pregnancy/postpartum, malignancy, antiphospholipid syndrome, Factor V Leiden, paroxysmal nocturnal hemoglobinuria, Behçet disease, hepatic vein web). [13]\n\n**Recognize the pattern:**\n- Subacute: weeks-to-months of worsening abdominal distension, RUQ pain, hepatomegaly, ascites with high SAAG (transudate from portal HTN).\n- Acute: severe RUQ pain + rapid jaundice + ALF-like presentation can occur with sudden complete hepatic vein occlusion.\n- LFTs: variable — moderately elevated AST/ALT, climbing bili, INR rising as hepatocyte loss progresses.\n- Caudate lobe sparing on imaging (caudate has separate venous drainage to IVC).\n\n**Next 5 minutes (ED-actionable):**\n- IV × 2, monitor\n- CBC, CMP, fractionated bili, INR/PT, AST/ALT, **pregnancy test**, type & screen\n- **Hepatic vein Doppler ultrasound** — non-invasive, sensitive (~85%) — shows absent/reversed flow, web, or thrombus\n- **CT venogram or MR venogram** for confirmation and intervention planning\n- Hepatology + IR consult emergent — TIPS is the typical first-line intervention; transplant if hepatic decompensation\n- **Anticoagulation** — heparin gtt or LMWH while bridging to definitive therapy\n- Manage ascites (diuretics + sodium restriction, large-volume paracentesis if tense)\n\n**Hypercoagulability workup to initiate (results return inpatient — do not delay imaging/heparin waiting on these):**\n- JAK2 V617F (for myeloproliferative neoplasm)\n- Antiphospholipid panel (lupus anticoagulant, anti-cardiolipin, anti-β2-glycoprotein)\n- Factor V Leiden, prothrombin G20210A\n- PNH flow cytometry (CD55/CD59)\n- Protein C, Protein S, antithrombin (interpret off anticoagulation when possible)\n\n🛑 Do NOT discharge an unexplained ascites + jaundice + hepatomegaly patient without ruling out Budd-Chiari — Doppler US is fast and sensitive.\n🛑 Do NOT defer the hypercoagulability workup to outpatient — the etiology drives long-term anticoagulation strategy and BC can recur catastrophically.","citation":[13],"recommendation":"Hepatic vein Doppler US first. CT/MR venogram for planning. Heparin + hepatology + IR. TIPS / transplant per response.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'aj-exc-budd-chiari' AND tree_id = 'acute-jaundice-hub';

